using UnityEngine;

/// <summary>
/// Kinetic ball, created by the Cannon: everything it hits scores on a curve of its
/// speed, so a cannonball fired hard is worth many times one trickling downhill.
/// See <see cref="KineticScoring"/> for the curve.
///
/// Speed is sampled from the collision's relative velocity at the moment of impact
/// rather than the rigidbody afterwards, because by the time scoring runs the
/// bounce response has already changed the rigidbody's velocity.
/// </summary>
public sealed class CannonballBall : Ball
{
    public const string DefinitionId = "Cannonball";

    private Rigidbody _body;
    private float _impactSpeed;

    private void Awake()
    {
        _body = GetComponent<Rigidbody>();
    }

    protected override void OnCollisionEnter(Collision collision)
    {
        _impactSpeed = collision.relativeVelocity.magnitude;
        base.OnCollisionEnter(collision);
        _impactSpeed = 0f;
    }

    protected override void AddScore(float amount, TypeOfScore typeOfScore, Transform pos)
    {
        base.AddScore(amount * KineticMultiplier(), typeOfScore, pos);
    }

    /// <summary>
    /// The impact speed while a collision is being scored; otherwise the ball's
    /// current speed, which is what trigger-based scoring has to go on.
    /// </summary>
    private float KineticMultiplier()
    {
        float speed = _impactSpeed > 0f
            ? _impactSpeed
            : (_body != null ? _body.linearVelocity.magnitude : 0f);

        return KineticScoring.Multiplier(speed);
    }
}
